import 'dart:math' as math;import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_html/flutter_html.dart';import 'package:flutter_svg/flutter_svg.dart';import 'package:mashtoz_flutter/domens/models/book_data/category_lsit.dart';import 'package:mashtoz_flutter/domens/models/book_data/content_list.dart';import 'package:mashtoz_flutter/domens/models/book_data/data.dart';import 'package:mashtoz_flutter/domens/models/book_data/lessons.dart';import 'package:mashtoz_flutter/domens/repository/user_data_provider.dart';import 'package:mashtoz_flutter/ui/widgets/main_page/bottom_bars_pages/bottom_bar_menu_pages.dart';import 'package:mashtoz_flutter/ui/widgets/main_page/library_pages/books_page.dart';import 'package:responsive_grid_list/responsive_grid_list.dart';import 'package:tab_indicator_styler/tab_indicator_styler.dart';import 'package:url_launcher/url_launcher.dart';import '../../../../config/palette.dart';import '../../helper_widgets/menuShow.dart';import '../library_pages/book_read_screen.dart';import '../main_menu_pages/audio_library/audio_librar_data_show.dart';class AccountPage extends StatelessWidget {  const AccountPage({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return Scaffold(        backgroundColor: Palette.textLineOrBackGroundColor,        extendBodyBehindAppBar: true,        body: CustomScrollView(          slivers: [            SliverAppBar(              flexibleSpace: Align(                alignment: Alignment.centerLeft,                child: Padding(                  padding: const EdgeInsets.only(                    left: 50.0,                    top: 23.0,                  ),                  child: Container(                    height: 73,                    padding: EdgeInsets.only(top: 18),                    child: Text(                      'Իմ հաշիվը',                      style: TextStyle(                          fontSize: 16,                          letterSpacing: 1,                          fontFamily: 'GHEAGrapalat',                          fontWeight: FontWeight.w700,                          color: Palette.appBarTitleColor),                    ),                  ),                ),              ),              leading: SizedBox(                width: 8,                height: 14,                child: SvgPicture.asset(                  'assets/images/Favorite_2 2.svg',                  fit: BoxFit.none,                ),              ),              expandedHeight: 73,              backgroundColor: Palette.textLineOrBackGroundColor,              elevation: 0,              automaticallyImplyLeading: false,              systemOverlayStyle: SystemUiOverlayStyle(                  statusBarColor: Color.fromRGBO(25, 4, 18, 1)),              actions: const [                Padding(                  padding: EdgeInsets.only(right: 20.0),                  child: MenuShow(),                ),              ],            ),            SliverFillRemaining(              child: DelegateChild(),            )          ],        ));  }}class DelegateChild extends StatefulWidget {  DelegateChild({    Key? key,  }) : super(key: key);  @override  State<DelegateChild> createState() => _DelegateChildState();}class _DelegateChildState extends State<DelegateChild>    with SingleTickerProviderStateMixin {  final userDataProvider = UserDataProvider();  Future<List<UserAccount>?>? favoriteFuture;  late TabController _tabController;  var types = <String>[    'libraries',    'encyclopedias',    'lessons',    'audiolibraries',    'armenians',  ];  int drawableIndex = 0;  Widget buildList(      {required Content? data, required int listCount,required String? type}) {    if (data != null ) {      if (drawableIndex == 0 && type!.contains(types[drawableIndex])) {        return listCount % 2 != 0            ? Transform(            alignment: Alignment.center,            transform: Matrix4.rotationY(math.pi),            child: Padding(              padding: const EdgeInsets.all(15.0),              child: BookCard(                isFromAccoungel: true,                isOdd: true,                book: data,                bookId: data.id,                categorys: BookCategory(                  categoryTitle: data.title!,                  id: data.id!,                  title: data.title!,                  type: 'librarian',                ),              ),            ))            : Padding(          padding: const EdgeInsets.all(15.0),          child: BookCard(            isFromAccoungel: true,            isOdd: false,            book: data,            bookId: data.id,            categorys: BookCategory(              categoryTitle: data.title!,              id: data.id!,              title: data.title!,              type: 'librarian',            ),          ),        );      } else if (drawableIndex == 1 && type!.contains(types[drawableIndex])) {        return carachtersList(data, listCount,type);      } else if (drawableIndex == 2 && type!.contains(types[drawableIndex])) {        return listCount % 2 != 0            ? Transform(          alignment: Alignment.center,          transform: Matrix4.rotationY(math.pi),          child: ITLesson(            isOdd: true,            italianLesson: Lessons(                id: data.id,                image: data.image,                title: data.title,                link: data.link,                number: data.number),          ),        )            : ITLesson(          isOdd: false,          italianLesson: Lessons(              id: data.id,              image: data.image,              title: data.title,              link: data.link,              number: data.number),        );        // return ITLesson(        //   italianLesson: Lessons(        //       id: data.id,        //       image: data.image,        //       title: data.title,        //       link: data.videoLink,        //       number: data.number),        //   isOdd: index % 2 != 0 ? false : true,        // );      } else if (drawableIndex == 3 && type!.contains(types[drawableIndex])) {        return carachtersList(data, listCount,type);      }      else if (drawableIndex == 4 && type!.contains('italians') || type!.contains(types[drawableIndex]) ) {        return dictionsyaLists(data, listCount,type);      }    }    return const SizedBox();  }  @override  void initState() {    _tabController = TabController(        length: listAccountElements.length,        vsync: this,        initialIndex: 0,        animationDuration: Duration.zero);    favoriteFuture = userDataProvider.getFavorites();    super.initState();  }  Widget carachtersList(Content data, int index,String type) {    Data encyclopediaBody = Data(id:data.id,title: data.title,body: data.body,type: type,explanation: data.explanation,        firstCharacter: data.first_character,summary: data.summary,video_link: data.videoLink ,sharurl: data.sharurl,author: data.author);    return GestureDetector(      onTap: () {        Navigator.push(            context,            MaterialPageRoute(                builder: (_) => type == 'audiolibraries' ? AudioLibraryDataShow(adbId: encyclopediaBody.id.toString(),firstCharacter: encyclopediaBody.firstCharacter,):BookReadScreen(                  encyId: encyclopediaBody.id.toString(),                  saveId: encyclopediaBody.id,                  encyclopediaBody:encyclopediaBody ,                ) ));      },      child: Container(        padding: EdgeInsets.only(right: 20.0, left: 22.0),        child: Column(          children: [            SizedBox(              height: 30,            ),            Row(              mainAxisAlignment: MainAxisAlignment.start,              crossAxisAlignment: CrossAxisAlignment.start,              children: [                Align(                  alignment: Alignment.topCenter,                  child: Padding(                    padding: const EdgeInsets.only(top: 0.0),                    child: Text(                      '0${index + 1}',                      style: TextStyle(                        color: Palette.main,                        fontFamily: 'GHEAGrapalat',                        fontSize: 16.0,                        fontWeight: FontWeight.w400,                      ),                    ),                  ),                ),                SizedBox(width: 10.0),                Align(                  alignment: Alignment.topLeft,                  child: Container(                    width: 260,                    child: Text(                      '${data.title}',                      style: TextStyle(                          fontFamily: 'GHEAGrapalat',                          fontSize: 16.0,                          fontWeight: FontWeight.w700,                          color: Color.fromRGBO(113, 141, 156, 1)),                      textAlign: TextAlign.start,                    ),                  ),                ),              ],            ),            Divider(              thickness: 1,              color: Color.fromRGBO(226, 224, 224, 1),            )          ],        ),      ),    );  }Widget dictionsyaLists(Content data, int index,String type) {  Data encyclopediaBody = Data(id:data.id,title: data.title,body: data.body,type: type,explanation: data.explanation,  firstCharacter: data.first_character,summary: data.summary,video_link: data.videoLink ,sharurl: data.sharurl,author: data.author);  return  ExpansionTile(    title: Text(      '${encyclopediaBody.title}',      style: TextStyle(        fontFamily: 'GHEAGrapalat',        fontSize: 16,        fontWeight: FontWeight.w700,        letterSpacing: 1,      ),    ),    controlAffinity: ListTileControlAffinity.leading,    leading: SvgPicture.asset('assets/images/line24.svg'),    initiallyExpanded: false,    children: [      Container(        color: Color.fromRGBO(246, 246, 246, 1),        child: ListTile(          title: Html(              shrinkWrap: true,              onLinkTap: (url, _, __, ___) async {                print("Opening $url...");                if(url!=null){                  if(url.contains('http') || url.contains('https') ){                    if (await canLaunch(url)) {                      await launch(                        url,                      );                    } else {                      throw 'Could not launch $url';                    }                  }                }},              onImageTap: (src, _, __, ___) {                print(src);              },              onImageError: (exception, stackTrace) {                print(exception);              },              data: '''${encyclopediaBody.body} '''),        ),      ),    ],  );  }  Widget buildData(String? type) {    return Container(      padding: EdgeInsets.only(left: 10.0, right: 10.0),      child: FutureBuilder<List<UserAccount>?>(        future: favoriteFuture,        builder: (context, snapshot) {          if (snapshot.connectionState == ConnectionState.waiting) {            return Center(              child: CircularProgressIndicator(                strokeWidth: 2.0,                color: Palette.main,              ),            );          } else if (snapshot.connectionState == ConnectionState.done) {            if (snapshot.hasError) {              return Text('Something went wrong');            } else if (snapshot.hasData && snapshot.data!.isNotEmpty) {              final data = snapshot.data!;              // var users = data.where((item) => item.type == type ?? "italians").toList();              List<UserAccount> users = data.where((UserAccount item) => item.type == "italians" || item.type == type).toList();              if(users.isEmpty) {                return  const Center(                child: Text(                  'Դեռևս գրառումներ չկան',                  style: TextStyle(                    fontSize: 16,                    fontWeight: FontWeight.w400,                    color: Palette.barColor,                  ),                ),              );              }              //var users = data.where((element) => element.type!.contains(types[drawableIndex])).toList();              print('im usersr $users');              return   MyResponsiveGridList(                typeId: users.map((e) => e).toList(),                  userDataProvider:userDataProvider,                horizontalGridSpacing: 10, // Horizontal space between grid items                  minItemWidth:                  388, // The minimum item width (can be smaller, if the layout constraints are smaller)                  minItemsPerRow:                  1, verticalGridSpacing: 10, rowMainAxisAlignment: MainAxisAlignment.center,                children: users.reversed.map((data) => buildList(                    type: data!.type,                    data: data.content,                    listCount: users.length                )).toList()) ;            } else {              return Center(                child: Text(                  'Դեռևս գրառումներ չկան',                  style: TextStyle(                    fontSize: 16,                    fontWeight: FontWeight.w400,                    color: Palette.barColor,                  ),                ),              );            }          } else {            return Text('State: ${snapshot.connectionState}');          }        },      ),    );  }  @override  Widget build(BuildContext context) {    return DefaultTabController(      initialIndex: 0,      length: listAccountElements.length,      child: Scaffold(        backgroundColor: Palette.textLineOrBackGroundColor,        appBar: PreferredSize(          preferredSize: Size(18.0, 50.0),          child: Container(            color: Color.fromRGBO(246, 246, 246, 1),            child: Padding(              padding: const EdgeInsets.only(left: 20.0),              child: TabBar(                  indicatorWeight: 2,                  unselectedLabelColor: const Color.fromRGBO(122, 108, 115, 1),                  labelColor: const Color.fromRGBO(251, 196, 102, 1),                  indicatorColor: Colors.amber,                  indicator: MaterialIndicator(                    color: Colors.amber,                    height: 2,                    topLeftRadius: 0,                    topRightRadius: 0,                    bottomLeftRadius: 5,                    bottomRightRadius: 5,                    tabPosition: TabPosition.top,                    paintingStyle: PaintingStyle.fill,                  ),                  controller: _tabController,                  isScrollable: true,                  labelPadding: const EdgeInsets.symmetric(horizontal: 15),                  onTap: (index) {                    setState(() {                      drawableIndex = index;                    });                   favoriteFuture = userDataProvider.getFavorites();                  },                  tabs: listAccountElements.map((tabName) {                    return Tab(                      child: Text(                        tabName,                        textAlign: TextAlign.center,                        style: TextStyle(                          fontFamily: 'GHEABrapalat',                          fontSize: 14,                          fontWeight: FontWeight.w400,                          letterSpacing: 1,                          color: listAccountElements                              .toString()                              .toLowerCase()                              .contains(tabName.toLowerCase())                              ? null                              : Color.fromRGBO(186, 166, 177, 1),                        ),                      ),                    );                  }).toList()),            ),          ),        ),        body: TabBarView(            physics: const NeverScrollableScrollPhysics(),            controller: _tabController,          children: types.map((type) {            return buildData(type);          }).toList(),        ),            // children: listAccountElements            //     .map(            //       (e) => listAccountElements            //       .toString()            //       .toLowerCase()            //       .contains(e.toLowerCase())            //       ? buildData()            //       : Center(            //     child: Text('Դեռևս գրառումներ չկան',style: TextStyle(color: Palette.barColor),),            //   ),            // )            //     .toList()),        //     ))      ),    );  }}var listAccountElements = [  'Գրադարան',  'Հանրագիտարան',  'Իտալերենի դասեր', // 'Համաբարբառ',  'Ձայնադարան',  'Իտալերեն֊Հայերեն\nԲառարան',  //'Պատկերադարան'];class MyResponsiveGridList extends AbstractResponsiveGridList{ final UserDataProvider userDataProvider; final List<UserAccount?>? typeId;const  MyResponsiveGridList({required this.typeId,required this.userDataProvider,required double minItemWidth, required int minItemsPerRow, required double horizontalGridSpacing, required double verticalGridSpacing, required MainAxisAlignment rowMainAxisAlignment, required List<Widget> children}) : super(minItemWidth: minItemWidth, minItemsPerRow: minItemsPerRow, horizontalGridSpacing: horizontalGridSpacing, verticalGridSpacing: verticalGridSpacing, rowMainAxisAlignment: rowMainAxisAlignment, children: children);  @override  Widget build(BuildContext context) {  return LayoutBuilder(  builder: (BuildContext context, BoxConstraints constraints) {  // The abstract class has a function to generate the grid from  // the constructor's paramters and the layout constraints max width  var items = getResponsiveGridListItems(constraints.maxWidth);  print('Imest lenght : ${children.length} type lenght: ${typeId?.length}');  var customList = ListView.builder(    shrinkWrap: true,    itemCount: children.length,    itemBuilder: (context, index) {      return Dismissible(        key: Key('${typeId![index]?.type}'),        direction: DismissDirection.endToStart,        onDismissed: (direction) async {          // remove the item from the list          children.removeAt(index);          // create a map of data to delete from user data provider          Map<String, dynamic> delete = {};          await userDataProvider.fetchUserInfo().then((value) {            delete = <String, dynamic>{              'type':  typeId![index]?.type,              'type_id': typeId![index]?.type_id,              'customer_id': value?.id,            };          });          await userDataProvider.deleteFavorite(delete);        },        background: Container(          color: Colors.red,          child: Icon(Icons.delete),          alignment: Alignment.centerRight,          padding: EdgeInsets.symmetric(horizontal: 20),        ),        child: Stack(          children: [            children[index],            Positioned.fill(                bottom: 10,              child:  Align(                  alignment: Alignment.centerRight,                  child: Icon(Icons.swipe_left,color: Palette.barColor,)),            )          ],        ),      );    },  );  return customList;  },  );  }}